def longestZeroOneBlock(s):
    best = 0
    prev_zeros = 0   # size of the zero group directly before the current group (0 if none)
    cur = 0
    ch = ''
    for c in s:
        if c == ch:
            cur += 1
        else:
            if ch == '1':
                best = max(best, 2 * min(prev_zeros, cur))
            prev_zeros = cur if ch == '0' else 0
            ch = c
            cur = 1
    if ch == '1':
        best = max(best, 2 * min(prev_zeros, cur))
    return best
